    public static int IndexFor(int sampleRate) => sampleRate switch
    {
        96000 => 0, 88200 => 1, 64000 => 2, 48000 or 49716 => 3,
        44100 => 4, 32000 => 5, 24000 => 6, 22050 => 7,
        16000 => 8, 12000 => 9, 11025 or 11111 => 10,
        8000 => 11, 18900 => 12, 37800 => 13,
        _ => throw new ArgumentOutOfRangeException(nameof(sampleRate))
    };

