    public static ReadOnlySpan<float> ButterFor(int sampleRate) => Butter[IndexFor(sampleRate)];
    public static int WindowSamples(int sampleRate)
    {
        _ = IndexFor(sampleRate);
        return (int)Math.Ceiling(sampleRate * .050);
    }
